cat > /workspace/pkg/hosts/hosts.go << 'EOF'
package hosts

import (
	"bufio"
	"fmt"
	"os"
	"strings"
)

const (
	ManagedBlockMarker   = "##################################################################"
	ManagedBlockComment  = "# Content under this line is handled by hostctl. DO NOT EDIT."
	ProfileOnPrefix      = "# profile.on "
	ProfileOffPrefix     = "# profile.off "
	ProfileEndMarker     = "# end"
)

type Entry struct {
	IP      string
	Domain  string
	Profile string
	Status  string // "on" or "off"
	Raw     string // raw line from file
}

type Profile struct {
	Name    string
	Status  string // "on" or "off"
	Entries []Entry
}

type HostsFile struct {
	Path       string
	Entries    []Entry
	Profiles   map[string]*Profile
	Managed    bool
	UnManaged  []string // lines before the managed block
}

func NewHostsFile(path string) *HostsFile {
	return &HostsFile{
		Path:     path,
		Profiles: make(map[string]*Profile),
	}
}

func (h *HostsFile) Read() error {
	file, err := os.Open(h.Path)
	if err != nil {
		return err
	}
	defer file.Close()

	scanner := bufio.NewScanner(file)
	var inManagedBlock bool
	var currentProfile *Profile
	var currentProfileStatus string

	for scanner.Scan() {
		line := scanner.Text()

		// Check for managed block marker
		if strings.Contains(line, ManagedBlockComment) {
			inManagedBlock = true
			h.Managed = true
			continue
		}

		if !inManagedBlock {
			// Unmanaged content
			h.UnManaged = append(h.UnManaged, line)
			// Parse unmanaged entries (lines without comments)
			if line != "" && !strings.HasPrefix(strings.TrimSpace(line), "#") {
				parts := strings.Fields(line)
				if len(parts) >= 2 {
					entry := Entry{
						IP:      parts[0],
						Domain:  parts[1],
						Profile: "default",
						Status:  "on",
						Raw:     line,
					}
					h.Entries = append(h.Entries, entry)

					// Add to default profile
					if _, ok := h.Profiles["default"]; !ok {
						h.Profiles["default"] = &Profile{
							Name:   "default",
							Status: "on",
						}
					}
					h.Profiles["default"].Entries = append(h.Profiles["default"].Entries, entry)
				}
			}
			continue
		}

		// In managed block
		if strings.HasPrefix(line, ProfileOnPrefix) {
			// Profile start with "on"
			profileName := strings.TrimPrefix(line, ProfileOnPrefix)
			profileName = strings.TrimSpace(profileName)
			currentProfileStatus = "on"
			currentProfile = &Profile{
				Name:   profileName,
				Status: "on",
			}
			h.Profiles[profileName] = currentProfile
			continue
		}

		if strings.HasPrefix(line, ProfileOffPrefix) {
			// Profile start with "off"
			profileName := strings.TrimPrefix(line, ProfileOffPrefix)
			profileName = strings.TrimSpace(profileName)
			currentProfileStatus = "off"
			currentProfile = &Profile{
				Name:   profileName,
				Status: "off",
			}
			h.Profiles[profileName] = currentProfile
			continue
		}

		if strings.TrimSpace(line) == ProfileEndMarker {
			currentProfile = nil
			currentProfileStatus = ""
			continue
		}

		if currentProfile != nil && line != "" {
			// Parse entry in profile
			if strings.HasPrefix(line, "# ") && currentProfileStatus == "off" {
				// Entry is commented out (disabled)
				entry := strings.TrimPrefix(line, "# ")
				parts := strings.Fields(entry)
				if len(parts) >= 2 {
					e := Entry{
						IP:      parts[0],
						Domain:  parts[1],
						Profile: currentProfile.Name,
						Status:  "off",
						Raw:     line,
					}
					h.Entries = append(h.Entries, e)
					currentProfile.Entries = append(currentProfile.Entries, e)
				}
			} else if !strings.HasPrefix(line, "#") && currentProfileStatus == "on" {
				// Entry is active
				parts := strings.Fields(line)
				if len(parts) >= 2 {
					e := Entry{
						IP:      parts[0],
						Domain:  parts[1],
						Profile: currentProfile.Name,
						Status:  "on",
						Raw:     line,
					}
					h.Entries = append(h.Entries, e)
					currentProfile.Entries = append(currentProfile.Entries, e)
				}
			}
		}
	}

	return scanner.Err()
}

func (h *HostsFile) Save() error {
	file, err := os.Create(h.Path)
	if err != nil {
		return err
	}
	defer file.Close()

	writer := bufio.NewWriter(file)

	// Write unmanaged content
	for _, line := range h.UnManaged {
		fmt.Fprintln(writer, line)
	}

	if len(h.Profiles) > 0 {
		fmt.Fprintln(writer, "")
		fmt.Fprintln(writer, ManagedBlockMarker)
		fmt.Fprintln(writer, ManagedBlockComment)
		fmt.Fprintln(writer, ManagedBlockMarker)

		// Write managed profiles
		for _, profile := range h.Profiles {
			if profile.Name == "default" {
				continue
			}

			fmt.Fprintln(writer, "")

			if profile.Status == "on" {
				fmt.Fprintf(writer, "# profile.on %s\n", profile.Name)
			} else {
				fmt.Fprintf(writer, "# profile.off %s\n", profile.Name)
			}

			for _, entry := range profile.Entries {
				if profile.Status == "off" {
					fmt.Fprintf(writer, "# %s %s\n", entry.IP, entry.Domain)
				} else {
					fmt.Fprintf(writer, "%s %s\n", entry.IP, entry.Domain)
				}
			}

			fmt.Fprintln(writer, "# end")
		}
	}

	return writer.Flush()
}

func (h *HostsFile) GetAllEntries() []Entry {
	return h.Entries
}

func (h *HostsFile) AddEntry(profileName string, ip string, domain string) {
	if _, ok := h.Profiles[profileName]; !ok {
		h.Profiles[profileName] = &Profile{
			Name:   profileName,
			Status: "on",
		}
	}

	entry := Entry{
		IP:      ip,
		Domain:  domain,
		Profile: profileName,
		Status:  "on",
	}
	h.Profiles[profileName].Entries = append(h.Profiles[profileName].Entries, entry)
	h.Entries = append(h.Entries, entry)
}

func (h *HostsFile) ReplaceProfile(profileName string, entries []Entry) {
	if profile, ok := h.Profiles[profileName]; ok {
		// Remove old entries
		newEntries := []Entry{}
		for _, e := range h.Entries {
			if e.Profile != profileName {
				newEntries = append(newEntries, e)
			}
		}
		h.Entries = newEntries

		// Add new entries
		profile.Entries = entries
		for _, e := range entries {
			e.Profile = profileName
			e.Status = "on"
			h.Entries = append(h.Entries, e)
		}
	}
}

func (h *HostsFile) RemoveProfile(profileName string) {
	if profileName == "default" {
		return
	}

	delete(h.Profiles, profileName)
	newEntries := []Entry{}
	for _, e := range h.Entries {
		if e.Profile != profileName {
			newEntries = append(newEntries, e)
		}
	}
	h.Entries = newEntries
}

func (h *HostsFile) EnableProfile(profileName string) {
	if profile, ok := h.Profiles[profileName]; ok {
		profile.Status = "on"
		for i := range profile.Entries {
			profile.Entries[i].Status = "on"
		}
		for i := range h.Entries {
			if h.Entries[i].Profile == profileName {
				h.Entries[i].Status = "on"
			}
		}
	}
}

func (h *HostsFile) DisableProfile(profileName string) {
	if profile, ok := h.Profiles[profileName]; ok {
		profile.Status = "off"
		for i := range profile.Entries {
			profile.Entries[i].Status = "off"
		}
		for i := range h.Entries {
			if h.Entries[i].Profile == profileName {
				h.Entries[i].Status = "off"
			}
		}
	}
}

func (h *HostsFile) ToggleProfile(profileName string) {
	if profile, ok := h.Profiles[profileName]; ok {
		if profile.Status == "on" {
			h.DisableProfile(profileName)
		} else {
			h.EnableProfile(profileName)
		}
	}
}
EOF

