cat > /workspace/pkg/output/formatter.go << 'EOF'
package output

import (
	"encoding/json"
	"fmt"
	"io"
	"strings"

	"github.com/gookit/color"
	"github.com/jedib0t/go-pretty/v6/table"
	"hostctl/pkg/hosts"
)

type Formatter struct {
	Format  string
	NoColor bool
	Columns []string
	Writer  io.Writer
}

func NewFormatter(format string, noColor bool, columns []string, writer io.Writer) *Formatter {
	if format == "raw" {
		format = "raw"
	}
	return &Formatter{
		Format:  format,
		NoColor: noColor,
		Columns: columns,
		Writer:  writer,
	}
}

func (f *Formatter) PrintInfo(message string) {
	if f.NoColor {
		fmt.Fprintf(f.Writer, "[ℹ] %s\n\n", message)
	} else {
		fmt.Fprintf(f.Writer, "%s\n\n", color.Info.Sprintf("[ℹ] %s", message))
	}
}

func (f *Formatter) PrintSuccess(message string) {
	if f.NoColor {
		fmt.Fprintf(f.Writer, "[✔] %s\n\n", message)
	} else {
		fmt.Fprintf(f.Writer, "%s\n\n", color.Success.Sprintf("[✔] %s", message))
	}
}

func (f *Formatter) PrintEntries(entries []hosts.Entry) {
	switch f.Format {
	case "json":
		f.printJSON(entries)
	case "markdown":
		f.printMarkdown(entries)
	case "raw":
		f.printRaw(entries)
	default:
		f.printTable(entries)
	}
}

func (f *Formatter) printTable(entries []hosts.Entry) {
	t := table.NewWriter()
	t.SetOutputMirror(f.Writer)

	// Determine columns
	cols := []string{"PROFILE", "STATUS", "IP", "DOMAIN"}
	if len(f.Columns) > 0 {
		cols = f.Columns
		// Normalize column names to uppercase
		for i, col := range cols {
			cols[i] = strings.ToUpper(strings.TrimSpace(col))
		}
	}

	// Set header
	headerRow := []interface{}{}
	for _, col := range cols {
		headerRow = append(headerRow, col)
	}
	t.AppendHeader(headerRow)

	// Group entries by profile
	profiles := make(map[string][]hosts.Entry)
	for _, e := range entries {
		profiles[e.Profile] = append(profiles[e.Profile], e)
	}

	// Add rows
	addedProfiles := make(map[string]bool)
	for _, e := range entries {
		if addedProfiles[e.Profile] && len(profiles[e.Profile]) > 1 {
			continue
		}

		row := []interface{}{}
		for _, col := range cols {
			switch col {
			case "PROFILE":
