		}
	}

	// Header
	for i, col := range cols {
		if i > 0 {
			fmt.Fprint(f.Writer, "\t")
		}
		fmt.Fprintf(f.Writer, "%s", col)
	}
	fmt.Fprint(f.Writer, "\n")

	// Rows
	for _, e := range entries {
		for i, col := range cols {
			if i > 0 {
				fmt.Fprint(f.Writer, "\t")
			}
			switch col {
			case "PROFILE":
				fmt.Fprintf(f.Writer, "%s", e.Profile)
			case "STATUS":
				fmt.Fprintf(f.Writer, "%s", e.Status)
			case "IP":
				fmt.Fprintf(f.Writer, "%s", e.IP)
			case "DOMAIN", "HOST":
				fmt.Fprintf(f.Writer, "%s", e.Domain)
			}
		}
		fmt.Fprint(f.Writer, "\n")
	}
}
