package main

import (
	"fmt"
	"os"
	"path/filepath"
	"runtime"
	"strings"
)

func main() {
	// Set default hosts file based on OS
	hostsFilePath := "/etc/hosts"
	if runtime.GOOS == "windows" {
		hostsFilePath = filepath.Join(os.Getenv("SystemRoot"), "System32", "Drivers", "etc", "hosts")
	}

	// Parse command line arguments
	args := os.Args[1:]

	if len(args) == 0 {
		showHelp()
		os.Exit(0)
	}

	// Global flags
	var outputFormat string = "table"
	var columns []string
	var noColor bool
	var quiet bool

	// Parse global flags first
	newArgs := []string{}
	for i := 0; i < len(args); i++ {
		arg := args[i]
		if arg == "-h" || arg == "--help" {
			if len(newArgs) == 0 {
				showHelp()
				os.Exit(0)
			}
			newArgs = append(newArgs, arg)
		} else if arg == "--version" || arg == "-v" {
			if arg == "--version" || (arg == "-v" && (len(newArgs) == 0 || !strings.Contains(newArgs[len(newArgs)-1], "wait"))) {
				fmt.Println("hostctl version dev")
				os.Exit(0)
			}
			newArgs = append(newArgs, arg)
		} else if arg == "--host-file" {
			if i+1 < len(args) {
				hostsFilePath = args[i+1]
				i++
			}
		} else if arg == "-o" || arg == "--out" {
			if i+1 < len(args) {
				outputFormat = args[i+1]
				i++
			}
		} else if arg == "--raw" {
			outputFormat = "raw"
		} else if arg == "-c" || arg == "--column" {
			if i+1 < len(args) {
				columns = strings.Split(args[i+1], ",")
				for j := range columns {
					columns[j] = strings.TrimSpace(columns[j])
