func backupCommand(ctx *Context, args []string) {
	hostsFile := hosts.NewHostsFile(ctx.HostsFilePath)
	if err := hostsFile.Read(); err != nil {
		fmt.Fprintf(os.Stderr, "Error reading hosts file: %v\n", err)
		os.Exit(1)
	}

	// Create backup filename with date
	backupPath := ctx.HostsFilePath + "." + time.Now().Format("20060102")

	backupFile, err := os.Create(backupPath)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error creating backup: %v\n", err)
		os.Exit(1)
	}
	defer backupFile.Close()

	sourceFile, err := os.Open(ctx.HostsFilePath)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error reading hosts file: %v\n", err)
		os.Exit(1)
	}
	defer sourceFile.Close()

	if _, err := backupFile.ReadFrom(sourceFile); err != nil {
		fmt.Fprintf(os.Stderr, "Error writing backup: %v\n", err)
		os.Exit(1)
	}

	if !ctx.Quiet {
		formatter := output.NewFormatter(ctx.OutputFormat, ctx.NoColor, ctx.Columns, os.Stdout)
		formatter.PrintInfo(fmt.Sprintf("Using hosts file: %s", ctx.HostsFilePath))
		formatter.PrintSuccess(fmt.Sprintf("Backup '%s' created.", backupPath))

		entries := hostsFile.GetAllEntries()
		formatter.PrintEntries(entries)
	}
}

func restoreCommand(ctx *Context, args []string) {
	// Look for --from flag
	var fromFile string
	for i := 0; i < len(args); i++ {
		if args[i] == "--from" && i+1 < len(args) {
			fromFile = args[i+1]
			break
		}
	}

	if fromFile == "" {
		fmt.Fprintf(os.Stderr, "Error: --from flag is required\n")
		os.Exit(1)
	}

	backupFile, err := os.Open(fromFile)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error reading backup file: %v\n", err)
		os.Exit(1)
	}
	defer backupFile.Close()

	outputFile, err := os.Create(ctx.HostsFilePath)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error creating hosts file: %v\n", err)
		os.Exit(1)
	}
	defer outputFile.Close()

	if _, err := outputFile.ReadFrom(backupFile); err != nil {
		fmt.Fprintf(os.Stderr, "Error writing hosts file: %v\n", err)
		os.Exit(1)
	}

	if !ctx.Quiet {
		formatter := output.NewFormatter(ctx.OutputFormat, ctx.NoColor, ctx.Columns, os.Stdout)
		formatter.PrintInfo(fmt.Sprintf("Using hosts file: %s", ctx.HostsFilePath))
		formatter.PrintSuccess("Hosts file restored.")
	}
}

func replaceCommand(ctx *Context, args []string) {
	if len(args) < 1 {
		fmt.Fprintf(os.Stderr, "Error: profile name required\n")
		os.Exit(1)
	}

	profileName := args[0]
	var fromFile string

	// Look for --from flag
	for i := 1; i < len(args); i++ {
		if args[i] == "-f" || args[i] == "--from" {
			if i+1 < len(args) {
				fromFile = args[i+1]
				break
			}
		}
	}

	hostsFile := hosts.NewHostsFile(ctx.HostsFilePath)
	if err := hostsFile.Read(); err != nil {
		fmt.Fprintf(os.Stderr, "Error reading hosts file: %v\n", err)
		os.Exit(1)
	}

	var entries []hosts.Entry
	if fromFile != "" {
		file, err := os.Open(fromFile)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Error reading file: %v\n", err)
			os.Exit(1)
		}
		defer file.Close()

		scanner := bufio.NewScanner(file)
		for scanner.Scan() {
			line := strings.TrimSpace(scanner.Text())
			if line == "" || strings.HasPrefix(line, "#") {
				continue
			}

			parts := strings.Fields(line)
			if len(parts) >= 2 {
				entries = append(entries, hosts.Entry{
					IP:     parts[0],
					Domain: parts[1],
				})
			}
		}

		if err := scanner.Err(); err != nil {
			fmt.Fprintf(os.Stderr, "Error reading file: %v\n", err)
			os.Exit(1)
		}
	}

	hostsFile.ReplaceProfile(profileName, entries)

	if err := hostsFile.Save(); err != nil {
		fmt.Fprintf(os.Stderr, "Error saving hosts file: %v\n", err)
		os.Exit(1)
	}

	if !ctx.Quiet {
		formatter := output.NewFormatter(ctx.OutputFormat, ctx.NoColor, ctx.Columns, os.Stdout)
		formatter.PrintInfo(fmt.Sprintf("Using hosts file: %s", ctx.HostsFilePath))

		allEntries := hostsFile.GetAllEntries()
		filtered := []hosts.Entry{}
		for _, e := range allEntries {
			if e.Profile == profileName {
				filtered = append(filtered, e)
			}
		}
		formatter.PrintEntries(filtered)
	}
}

func syncCommand(ctx *Context, args []string) {
	if len(args) < 1 {
		fmt.Fprintf(os.Stderr, "Error: sync subcommand required (docker or docker-compose)\n")
		os.Exit(1)
	}

	switch args[0] {
	case "docker":
		fmt.Fprintf(os.Stderr, "Error: docker sync not yet implemented\n")
		os.Exit(1)
	case "docker-compose":
		fmt.Fprintf(os.Stderr, "Error: docker-compose sync not yet implemented\n")
		os.Exit(1)
	default:
		fmt.Fprintf(os.Stderr, "Error: unknown sync subcommand: %s\n", args[0])
		os.Exit(1)
	}
}
